package de.cebrero.drwho.core;
import java.util.*;import java.io.*;
import static de.cebrero.drwho.core.CoreTest.*;
final class VoteAndRevealTest {
 static void run()throws Exception{
  MemoryStore store=new MemoryStore();Dice dice=new Dice();GameEngine e=engine(store,dice);String a=ready(e,"Alice","doctor"),b=ready(e,"Bob","dalek"),c=ready(e,"Cora","adipose");e.startDemo();
  check(e.portalState().setupStage.equals("voting"),"new adventure votes before roommaster search");check(e.portalState().voteStatus.contains("Alice")&&e.portalState().voteStatus.contains("Adipose"),"portal names characters still missing");
  long rev=revision(e.snapshot(a));String req=id();e.command(a,req,rev,"vote","1");check(e.snapshot(a).contains("\"choice\":1")&&e.snapshot(b).contains("\"choice\":0"),"own vote private, other choices not exposed");
  check(!e.portalState().voteStatus.contains("Alice"),"completed voter no longer marked missing");e.command(a,req,rev,"vote","1");rejects(IllegalArgumentException.class,()->cmd(e,a,"vote","2"));
  e.command(b,id(),rev,"vote","2");check(e.portalState().setupStage.equals("voting"),"concurrent original revisions accepted, offline last voter waits without timeout");
  GameEngine restored=engine(store,dice);check(restored.snapshot(a).equals(e.snapshot(a)),"partial votes survive host restart");cmd(restored,c,"vote","1");check(restored.portalState().setupStage.equals("voteResult")&&restored.portalState().objectiveText.equals(GameEngine.objectiveText(1)),"majority chooses first goal and displays result before search");
  check(restored.snapshot(c).contains("\"tied\":false"),"majority does not claim a tie");advance(restored);check(restored.portalState().setupStage.equals("selecting"),"result precedes selection animation");advance(restored);check(restored.portalState().setupStage.equals("offering"),"then normal roommaster request");
  MemoryStore tiedStore=new MemoryStore();GameEngine tied=engine(tiedStore,dice);String one=ready(tied,"One","doctor"),two=ready(tied,"Two","zygon");tied.startDemo();cmd(tied,one,"vote","1");String last=id();long before=revision(tied.snapshot(two));String result=tied.command(two,last,before,"vote","2");check(result.contains("\"tied\":true")&&result.contains("\"objective\":2"),"host resolves tie exactly once using its own random");int draws=dice.helperDraws;tied.command(two,last,before,"vote","2");GameEngine again=engine(tiedStore,dice);check(again.snapshot(two).equals(result)&&dice.helperDraws==draws,"last-vote retry and restart preserve tie result without reroll");
  GameEngine random=engine(new MemoryStore(),dice);String r=ready(random,"Random","doctor");random.startDemo();cmd(random,r,"vote","random");check(random.snapshot(r).contains("\"choice\":2")&&random.snapshot(r).contains("\"objective\":2"),"Zufall is a host-picked own vote");
  GameEngine removal=engine(new MemoryStore(),dice);String ra=ready(removal,"A","doctor"),rb=ready(removal,"B","dalek");removal.startDemo();cmd(removal,ra,"vote","1");removal.removePlayer(text(removal.snapshot(rb),"you"));check(removal.portalState().setupStage.equals("voteResult"),"host can remove absent voter, remaining complete votes resolve");removal.removePlayer(text(removal.snapshot(ra),"you"));check(!removal.preparing(),"last voter removal returns cleanly to lobby");
  MemoryStore failure=new MemoryStore();GameEngine failing=engine(failure,dice);String fa=ready(failing,"F","doctor");failing.startDemo();String initial=failing.snapshot(fa);failure.fail=true;rejects(IOException.class,()->cmd(failing,fa,"vote","1"));failure.fail=false;check(initial.equals(failing.snapshot(fa)),"failed vote save leaves previous committed state intact");
  MemoryStore dieStore=new MemoryStore();GameEngine die=engine(dieStore,dice);String da=ready(die,"Player","doctor"),db=ready(die,"Partner","dalek");start(die);begin(die,da);cmd(die,da,"roll","");String roll=die.portalState().rollId;long rollRev=revision(die.snapshot(da));
  check(!die.portalState().rollPresented&&die.portalState().die==0&&die.portalState().detail.contains("Spielerhandy"),"portal hides result and result story before client completion");
  GameEngine after=engine(dieStore,dice);check(!after.portalState().rollPresented&&after.portalState().die==0,"portal wait survives host restart");rejects(IllegalArgumentException.class,()->cmd(after,db,"ackRoll",roll));rejects(IllegalArgumentException.class,()->cmd(after,da,"ackRoll",id()));
  dieStore.fail=true;rejects(IOException.class,()->cmd(after,da,"ackRoll",roll));dieStore.fail=false;check(!after.portalState().rollPresented,"failed ACK storage does not reveal portal result");
  after.command(da,id(),0,"ackRoll",roll);check(after.portalState().rollPresented&&after.portalState().die==dice.face&&!after.portalState().events.isEmpty(),"only matching player ACK releases committed host result");check(revision(after.snapshot(da))==rollRev,"cosmetic ACK does not stale concurrent movement revisions");int rolls=dice.rolls;cmd(after,da,"ackRoll",roll);check(dice.rolls==rolls&&engine(dieStore,dice).portalState().rollPresented,"ACK retry persists without reroll or replay");
  byte[] modern=die.exportGame(),old=Arrays.copyOf(modern,modern.length-94);java.nio.ByteBuffer.wrap(old).putInt(4,10);MemoryStore oldStore=new MemoryStore();oldStore.data=old;GameEngine legacy=engine(oldStore,dice);check(legacy.playing()&&legacy.portalState().rollPresented&&legacy.portalState().die==dice.face,"format 10 running games keep their turn without retroactive vote or impossible ACK");
  cmd(die,da,"move","S");check(die.portalState().rollPresented,"first post-animation move recovers a lost cosmetic ACK");
  // Original drawings show north/west walls. Every rotation must agree with the physical visible plan.
  for(int rotation=0;rotation<4;rotation++){
   BoardPlan plan=new BoardPlan();plan.place(1,1,"corner",rotation);for(int[] pos:new int[][]{{1,0},{2,1},{1,2},{0,1}})plan.place(pos[0],pos[1],"floor",0);
   int[][] from={{2,2},{3,2},{2,3},{2,2}},to={{2,1},{4,2},{2,4},{1,2}};
   for(int d=0;d<4;d++){boolean wall=d==rotation||d==(rotation+3)%4;check(plan.canStep(from[d][0],from[d][1],to[d][0],to[d][1])!=wall&&plan.canStep(to[d][0],to[d][1],from[d][0],from[d][1])!=wall,"corner visible wall/open edge matches both movement directions at rotation "+rotation+" direction "+d);}
   for(int[] step:new int[][]{{2,2,3,2},{2,2,2,3},{3,2,3,3},{2,3,3,3}})check(plan.canStep(step[0],step[1],step[2],step[3])&&plan.canStep(step[2],step[3],step[0],step[1]),"all four internal corner fields stay mutually reachable");
  }
 }
}
